CREATE TABLE "apontamentos" (id BIGSERIAL PRIMARY KEY, "convocacao_id" text NOT NULL, "data_servico" date NOT NULL, "colaborador_id" text NOT NULL, "engenheiro" text NOT NULL, "status" text NOT NULL, "valor_extra" numeric NOT NULL DEFAULT 0, "observacao" text, "apontado_em" timestamp with time zone NOT NULL DEFAULT now(), "apontado_por" text, "retroativo" boolean NOT NULL DEFAULT false, "atualizado_em" timestamp with time zone NOT NULL DEFAULT now(), "tipo_diaria" text, "custo_pago" numeric, "custo_pago_definido_financeiro" boolean NOT NULL DEFAULT false, "valor_acordo" numeric NOT NULL DEFAULT 0, "valor_adicional_noturno" numeric NOT NULL DEFAULT 0, "custo_encargos_base" numeric, "custos_separados" boolean NOT NULL DEFAULT false, "migracao_sebrae_noturno_v2" boolean NOT NULL DEFAULT false);
CREATE TABLE "auditoria" (id BIGSERIAL PRIMARY KEY, "entidade" text NOT NULL, "entidade_id" text, "acao" text NOT NULL, "usuario" text, "ocorrido_em" timestamp with time zone NOT NULL DEFAULT now(), "antes" jsonb, "depois" jsonb, "contexto" jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE "cobrancas_teams" (id BIGSERIAL PRIMARY KEY, "data_execucao" date NOT NULL, "horario" text NOT NULL, "engenheiro" text NOT NULL, "email_teams" text, "qtd_pendentes" integer NOT NULL DEFAULT 0, "mensagem" text, "status" text NOT NULL DEFAULT 'ENVIADA'::text, "resposta_http" integer, "enviado_em" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE "colaboradores" (id BIGSERIAL PRIMARY KEY, "nome" text NOT NULL, "funcao" text NOT NULL DEFAULT 'INDEFINIDA'::text, "valor_diaria" numeric NOT NULL DEFAULT 241.74, "local_moradia" text, "ativo" boolean NOT NULL DEFAULT true);
CREATE TABLE "conflitos_convocacao" (id BIGSERIAL PRIMARY KEY, "colaborador_id" text NOT NULL, "colaborador_nome_snapshot" text, "data" date NOT NULL, "convocacao_existente_id" text, "engenheiro_original" text NOT NULL, "turno_original" text NOT NULL, "unidade_original" text, "engenheiro_tentativa" text NOT NULL, "turno_tentativa" text NOT NULL, "unidade_tentativa" text, "criado_em" timestamp with time zone NOT NULL DEFAULT now(), "resolvido" boolean NOT NULL DEFAULT false, "resolvido_em" timestamp with time zone, "resolvido_por" text, "contexto" jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE "convocacoes" (id BIGSERIAL PRIMARY KEY, "obra_id" bigint NOT NULL, "colaborador_id" bigint NOT NULL, "data" date NOT NULL, "engenheiro" text NOT NULL, "status" text NOT NULL DEFAULT 'Presente (Integral)'::text, "valor_extra" numeric NOT NULL DEFAULT 0, "observacao" text NOT NULL DEFAULT ''::text, "turno" text, "criado_em" timestamp with time zone, "criado_por" text, "tipo_diaria" text, "custo_pago" numeric, "custo_pago_definido_financeiro" boolean NOT NULL DEFAULT false, "valor_acordo" numeric NOT NULL DEFAULT 0, "valor_adicional_noturno" numeric NOT NULL DEFAULT 0, "custo_encargos_base" numeric, "custos_separados" boolean NOT NULL DEFAULT false, "migracao_sebrae_noturno_v2" boolean NOT NULL DEFAULT false);
CREATE TABLE "engenheiros_teams" ("engenheiro" text NOT NULL PRIMARY KEY, "email_teams" text, "ativo" boolean NOT NULL DEFAULT true, "atualizado_em" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE "erros_sistema" (id BIGSERIAL PRIMARY KEY, "codigo" text NOT NULL, "criado_em" timestamp with time zone NOT NULL DEFAULT now(), "ambiente" text NOT NULL DEFAULT 'producao'::text, "modulo" text NOT NULL DEFAULT ''::text, "acao" text NOT NULL DEFAULT ''::text, "tipo_erro" text NOT NULL DEFAULT ''::text, "mensagem" text NOT NULL DEFAULT ''::text, "detalhes" text NOT NULL DEFAULT ''::text, "usuario" text NOT NULL DEFAULT ''::text, "contexto" jsonb NOT NULL DEFAULT '{}'::jsonb, "resolvido" boolean NOT NULL DEFAULT false, "resolvido_em" timestamp with time zone);
CREATE TABLE "indisponibilidades" (id BIGSERIAL PRIMARY KEY, "colaborador_id" text NOT NULL, "colaborador_nome_snapshot" text, "motivo" text NOT NULL, "inicio" date NOT NULL, "fim" date NOT NULL, "observacao" text, "criado_em" timestamp with time zone NOT NULL DEFAULT now(), "criado_por" text, "ativo" boolean NOT NULL DEFAULT true, "legacy_origem_id" text);
CREATE TABLE "obras" (id BIGSERIAL PRIMARY KEY, "unidade" text NOT NULL, "nome" text NOT NULL, "trello_card_id" text, "trello_list_id" text, "trello_sync_em" timestamp with time zone, "trello_unidade_manual" boolean NOT NULL DEFAULT false);
CREATE TABLE "servicos_apontamento" (id BIGSERIAL PRIMARY KEY, "convocacao_id" text NOT NULL, "obra_id" text, "obra_nome_snapshot" text NOT NULL, "unidade_snapshot" text, "periodo" text, "principal" boolean NOT NULL DEFAULT false, "criado_em" timestamp with time zone NOT NULL DEFAULT now(), "atualizado_em" timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE "trello_snapshot" ("snapshot_id" integer NOT NULL, "listas" jsonb NOT NULL, "cards" jsonb NOT NULL, "atualizado_em" timestamp with time zone NOT NULL DEFAULT now(), "sincronizado_obras_em" timestamp with time zone, "ultima_tentativa_obras_em" timestamp with time zone, "ultimo_resultado_obras" jsonb);
CREATE UNIQUE INDEX test_ap_conv_id ON apontamentos(convocacao_id);